const SUPABASE_URL = "https://ehlvuzvqornzoaftekap.supabase.co";
const SUPABASE_ANON_KEY = "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImVobHZ1enZxb3Juem9hZnRla2FwIiwicm9sZSI6ImFub24iLCJpYXQiOjE3ODc4NjAxNjAsImV4cCI6MjEwMzQzNjE2MH0.WcoOjKndi-zFEcEJbC3jE4xze0FvO9_Qy_teEbfG2YA";

const STARTUPS = [{"id": "klubbase", "name": "KlubBase", "description": "An all-in-one digital platform for grassroots and semi-professional sports clubs, connecting club management, teams, players, parents, fans and sponsors through apps, communication, and live sports experiences.", "bg": "#1a3a5c", "logo": "data:image/png;base64,"}, {"id": "avento", "name": "Avento", "description": "A safe, verticalised marketplace for used extreme sports gear.", "bg": "#1a2a1a", "logo": "data:image/svg+xml;base64,"}, {"id": "booca", "name": "BOOCA Athletics", "description": "Builds sustainable, self-sufficient outdoor sports infrastructure combined with an AI and Computer Vision-powered ecosystem that turns any location into an interactive, gamified training ground.", "bg": "#1a2a1a", "logo": "data:image/png;base64,"}, {"id": "zeta", "name": "Zeta Industries", "description": "Developing a neck training exoskeleton for contact sports and physical therapy with integrated AI coach.", "bg": "#1a1a1a", "logo": "data:image/png;base64,"}, {"id": "trainpro", "name": "TrainPro", "description": "A digital platform connecting superfans with their favorite athlete.", "bg": "#1a2a1a", "logo": "data:image/jpeg;base64,"}, {"id": "hokd", "name": "HOKD", "description": "A golf app that unites social connection, round tracking, and AI-powered insights in one clear, elegant ecosystem, built for modern golfers.", "bg": "#0a2a1a", "logo": "data:image/png;base64,"}, {"id": "pin", "name": "PIN Sport App", "description": "A Swiss sports-tech marketplace and community platform using AI-powered, bias-aware matching to connect athletes, clubs, coaches, and professionals.", "bg": "#1a1a1a", "logo": "data:image/jpeg;base64,"}, {"id": "augo", "name": "Augo", "description": "The intelligence layer for endurance coaching: turns every workout, message and piece of athlete feedback into a clear signal of who needs the coach today.", "bg": "#1a1a1a", "logo": "data:image/png;base64,"}, {"id": "crion", "name": "Crion SA", "description": "A Swiss digital ecosystem connecting people, brands, companies and destinations with verified local outdoor professionals and bookable activities.", "bg": "#0a2030", "logo": "data:image/png;base64,"}, {"id": "contour", "name": "Contour", "description": "Replaces the ten fragmented tools a golf coach juggles today with one connected workflow, allowing them to focus on the interaction with the student.", "bg": "#0a2a1a", "logo": "data:image/png;base64,"}];

function validateEmail(email) {
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
}

export default function VotingApp() {
  const [votes, setVotes] = useState({});
  const [email, setEmail] = useState("");
  const [selectedId, setSelectedId] = useState(null);
  const [step, setStep] = useState("browse");
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(true);
  const [submitting, setSubmitting] = useState(false);
  const [sortedStartups, setSortedStartups] = useState(STARTUPS);

  async function loadVotes() {
    try {
      const res = await fetch(
        `${SUPABASE_URL}/rest/v1/votes?select=startup_id&verified=eq.true`,
        { headers: { apikey: SUPABASE_ANON_KEY, Authorization: `Bearer ${SUPABASE_ANON_KEY}` } }
      );
      const data = await res.json();
      const counts = {};
      data.forEach(row => { counts[row.startup_id] = (counts[row.startup_id] || 0) + 1; });
      setVotes(counts);
      setSortedStartups([...STARTUPS].sort((a,b) => (counts[b.id]||0) - (counts[a.id]||0)));
    } catch(e) { console.error(e); }
    setLoading(false);
  }

  useEffect(() => { loadVotes(); }, []);

  async function handleVote() {
    if (!validateEmail(email)) { setError("Please enter a valid email address."); return; }
    setError("");
    setSubmitting(true);
    try {
      const res = await fetch("/api/send-verification", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ email: email.toLowerCase().trim(), startup_id: selectedId })
      });
      const data = await res.json();
      if (res.status === 409) { setStep("already"); }
      else if (res.ok) { setStep("check_email"); }
      else { setError("Something went wrong. Please try again."); }
    } catch(e) {
      setError("Something went wrong. Please try again.");
    }
    setSubmitting(false);
  }

  const selected = STARTUPS.find(s => s.id === selectedId);
  const totalVotes = Object.values(votes).reduce((a,b) => a+b, 0);

  if (loading) return (
    <div style={{minHeight:"100vh", background:"#0d0d0d", display:"flex", alignItems:"center", justifyContent:"center"}}>
      <div style={{color:"#888", fontSize:14}}>Loading...</div>
    </div>
  );

  return (
    <div style={{minHeight:"100vh", background:"#0d0d0d", color:"#fff", fontFamily:"Inter, system-ui, sans-serif"}}>
      <div style={{borderBottom:"1px solid #1e1e1e", padding:"20px 24px", display:"flex", alignItems:"center", justifyContent:"space-between", position:"sticky", top:0, background:"#0d0d0d", zIndex:10}}>
        <div>
          <div style={{fontSize:11, letterSpacing:3, color:"#666", textTransform:"uppercase", marginBottom:4}}>Impulse Network x Sports Tech Nation</div>
          <div style={{fontSize:20, fontWeight:700, letterSpacing:-0.5}}>Startup Competition 2026 <span style={{color:"#c8ff00"}}>Vote</span></div>
        </div>
        <div style={{fontSize:11, color:"#666", textAlign:"right"}}>
          <div style={{color:"#c8ff00", fontSize:22, fontWeight:700}}>{totalVotes}</div>
          <div>total votes</div>
        </div>
      </div>

      <div style={{maxWidth:760, margin:"0 auto", padding:"32px 16px"}}>
        {step === "browse" && (
          <>
            <p style={{color:"#888", fontSize:14, marginBottom:28}}>Vote for your favourite startup. One vote per email address.</p>
            <div style={{display:"flex", flexDirection:"column", gap:12}}>
              {sortedStartups.map((s, idx) => (
                <div key={s.id} onClick={() => { setSelectedId(s.id); setStep("confirm"); setError(""); setEmail(""); }}
                  style={{background:"#141414", border:"1px solid #222", borderRadius:12, padding:"16px 20px", cursor:"pointer", display:"flex", alignItems:"center", gap:16, transition:"border-color 0.15s"}}
                  onMouseOver={e => e.currentTarget.style.borderColor="#c8ff00"}
                  onMouseOut={e => e.currentTarget.style.borderColor="#222"}>
                  <div style={{fontSize:12, color:"#555", width:20, textAlign:"center", flexShrink:0}}>{idx+1}</div>
                  <div style={{width:48, height:48, borderRadius:10, background:"#1e1e1e", display:"flex", alignItems:"center", justifyContent:"center", flexShrink:0, overflow:"hidden"}}>
                    <img src={s.logo} alt={s.name} style={{width:44, height:44, objectFit:"contain"}} />
                  </div>
                  <div style={{flex:1, minWidth:0}}>
                    <div style={{fontWeight:600, fontSize:15, marginBottom:3}}>{s.name}</div>
                    <div style={{fontSize:12, color:"#888", lineHeight:1.4, overflow:"hidden", textOverflow:"ellipsis", display:"-webkit-box", WebkitLineClamp:2, WebkitBoxOrient:"vertical"}}>{s.description}</div>
                  </div>
                  <div style={{textAlign:"center", flexShrink:0}}>
                    <div style={{fontSize:18, fontWeight:700, color:(votes[s.id]||0) > 0 ? "#c8ff00" : "#444"}}>{votes[s.id]||0}</div>
                    <div style={{fontSize:10, color:"#555"}}>votes</div>
                  </div>
                  <div style={{color:"#333", fontSize:18, flexShrink:0}}>›</div>
                </div>
              ))}
            </div>
          </>
        )}

        {step === "confirm" && selected && (
          <div style={{maxWidth:480, margin:"0 auto"}}>
            <button onClick={() => { setStep("browse"); setError(""); }} style={{background:"none", border:"none", color:"#666", cursor:"pointer", fontSize:13, marginBottom:24, padding:0}}>← Back</button>
            <div style={{background:"#141414", border:"1px solid #2a2a2a", borderRadius:16, padding:28, marginBottom:24}}>
              <div style={{display:"flex", alignItems:"center", gap:16, marginBottom:16}}>
                <div style={{width:64, height:64, borderRadius:12, background:"#1e1e1e", display:"flex", alignItems:"center", justifyContent:"center", overflow:"hidden"}}>
                  <img src={selected.logo} alt={selected.name} style={{width:58, height:58, objectFit:"contain"}} />
                </div>
                <div>
                  <div style={{fontWeight:700, fontSize:20}}>{selected.name}</div>
                  <div style={{fontSize:12, color:"#c8ff00"}}>{votes[selected.id]||0} votes</div>
                </div>
              </div>
              <p style={{fontSize:13, color:"#aaa", lineHeight:1.6, margin:0}}>{selected.description}</p>
            </div>
            <div style={{marginBottom:16}}>
              <div style={{fontSize:13, color:"#888", marginBottom:8}}>Enter your email to confirm your vote</div>
              <input type="email" placeholder="your@email.com" value={email}
                onChange={e => { setEmail(e.target.value); setError(""); }}
                onKeyDown={e => e.key === "Enter" && handleVote()}
                style={{width:"100%", background:"#1a1a1a", border:"1px solid #333", borderRadius:10, padding:"12px 16px", color:"#fff", fontSize:14, outline:"none", boxSizing:"border-box"}} />
              {error && <div style={{color:"#ff6b6b", fontSize:12, marginTop:8}}>{error}</div>}
            </div>
            <button onClick={handleVote} disabled={submitting}
              style={{width:"100%", background:"#c8ff00", color:"#0d0d0d", border:"none", borderRadius:10, padding:"14px", fontSize:15, fontWeight:700, cursor:submitting?"not-allowed":"pointer", opacity:submitting?0.7:1}}>
              {submitting ? "Sending..." : "Vote for " + selected.name}
            </button>
          </div>
        )}

        {step === "check_email" && (
          <div style={{textAlign:"center", maxWidth:400, margin:"60px auto"}}>
            <div style={{fontSize:48, marginBottom:16}}>📧</div>
            <div style={{fontSize:24, fontWeight:700, marginBottom:8}}>Check your email!</div>
            <div style={{color:"#888", fontSize:14, marginBottom:24}}>We sent a confirmation link to <span style={{color:"#c8ff00"}}>{email}</span>. Click it to confirm your vote.</div>
            <div style={{fontSize:12, color:"#555"}}>The link expires in 24 hours.</div>
            <button onClick={() => setStep("browse")} style={{marginTop:24, background:"#1a1a1a", border:"1px solid #333", borderRadius:10, padding:"12px 24px", color:"#aaa", cursor:"pointer", fontSize:13}}>Back to results</button>
          </div>
        )}

        {step === "already" && (
          <div style={{textAlign:"center", maxWidth:400, margin:"60px auto"}}>
            <div style={{fontSize:48, marginBottom:16}}>✋</div>
            <div style={{fontSize:22, fontWeight:700, marginBottom:8}}>Already voted</div>
            <div style={{color:"#888", fontSize:14, marginBottom:24}}>This email address has already been used to vote.</div>
            <button onClick={() => { setStep("browse"); setEmail(""); }} style={{background:"#1a1a1a", border:"1px solid #333", borderRadius:10, padding:"12px 24px", color:"#aaa", cursor:"pointer", fontSize:13}}>Back to results</button>
          </div>
        )}
      </div>
    </div>
  );
}
